// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    // fuzzed params: depositor private key seed and deposit amount
    function testFuzz_property(uint256 depositorKey, uint256 amt) public {
        vm.assume(amt <= VALUE_CAP);
        depositorKey = bound(depositorKey, 1, 115792089237316195423570985008687907852837564279074904382605163141518161494336);
        // keep amounts in a reasonable range and non-zero
        amt = bound(amt, 1, 1 ether);
        // pick an address from the private key seed
        address depositor = vm.addr(uint256(depositorKey));

        // fund depositor so they can send
        vm.deal(depositor, amt);

        // depositor adds to their balance
        vm.prank(depositor);
        c.addToBalance{value: amt}();

        // sanity: getter should reflect deposit
        uint balBefore = c.getBalance(depositor);
        // must equal amt for admissible inputs
        vm.assume(balBefore == amt);

        // deploy a helper that WILL revert when receiving funds
        Reverter rev = new Reverter();

        // Now test: have the depositor attempt to withdraw but target is depositor
        // We want the external call (msg.sender.call) to fail. To force c to call a failing
        // address, we need msg.sender to be the Reverter. So we impersonate Reverter and
        // call c.withdrawBalance() from it. But withdrawBalance sends to msg.sender,
        // therefore the callee that receives funds is the caller itself. So Reverter must
        // be the caller. To arrange that, we make the Reverter call c.withdrawBalance
        // on behalf of the depositor: first we need to set userBalance[Reverter] = amt.
        // So have depositor deposit, then transfer the internal accounting by directly
        // depositing from Reverter: instead, we will have depositor fund the contract's
        // balance and then we will manipulate by having Reverter call addToBalance via
        // a prank with msg.sender = Reverter while sending value. That's not possible
        // directly because vm.prank only sets msg.sender, not the msg.sender's private key,
        // but sending value in vm.prank uses the pranked address as sender. So simply:

        // fund the reverter externally so it can call addToBalance with value
        vm.deal(address(rev), 0);

        // Move the deposited balance from depositor to Reverter in contract storage by
        // having Reverter itself make an addToBalance call with value = amt. To do that
        // we need to transfer ETH to Reverter first.
        // Use depositor to send ETH to Reverter off-chain via vm.prank.
        vm.prank(depositor);
        (bool sent,) = depositor.call{value: amt}("\x00"); // send ETH to depositor? this is noop; instead use vm.deal below
        // The above attempt is unnecessary; simply ensure Reverter has ETH
        vm.deal(address(rev), amt);

        // Now have Reverter call addToBalance to set userBalance[Reverter] = amt
        vm.prank(address(rev));
        c.addToBalance{value: amt}();

        // ensure reverter's recorded balance in contract is amt
        uint revBal = c.getBalance(address(rev));
        vm.assume(revBal == amt);

        // Now have Reverter attempt to withdraw. Because Reverter's receive() reverts,
        // in the correct contract the withdraw should revert (and thus userBalance stays non-zero),
        // while the mutant that ignores send failures will not revert and will have set userBalance to 0.
        bool ok;
        vm.prank(address(rev));
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule we assert: for the correct contract, when the receiver reverts on being sent funds,
        // withdrawBalance must revert (so ok == false). This holds for all inputs. The mutant that ignores
        // failures will make ok == true for some inputs (and userBalance would be 0). We assert the correct
        // contract's behavior here: it must revert (ok == false).
        assertTrue(ok == false);
    }
}

// adversarial helper that reverts on receiving ETH
contract Reverter {
    receive() external payable {
        revert("fail receive");
    }
}
